SELECT rating_bucket, city, country_values, unique_countrys FROM (SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, city, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values, COUNT(DISTINCT rating) AS unique_countrys FROM suppliers GROUP BY CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END, city) AS x WHERE unique_countrys > 4
